import React from 'react';
import './Register.css';
import heartImg from '../../assets/heart.png'; 
import logo from '../../assets/Logo.png';
import { FaUser, FaEnvelope, FaLock, FaIdCard } from 'react-icons/fa'; 

const Register = () => {
  return (
    <div className="register-container">

      {/* Left Side */}
      <div
        className="left-side"
        style={{
          backgroundImage: `linear-gradient(rgba(0,0,0,0.25), rgba(0,0,0,0.25)), url(${heartImg})`,
        }}
      >
        <div className="logo-title-wrapper">
          <img src={logo} alt="logo" className="logo" />
          <div className="heart-title"><h1>Heart Diseases</h1></div>
        </div>
      </div>

      {/* Middle Gap */}
      <div className="middle-gap"></div>

      {/* Right Side */}
      <div className="right-side">
  <div className="register-content">

    <h2>Register Page</h2>

    <div className="input-group">
      <input type="email" placeholder="Email" />
      <FaEnvelope className="input-icon" />
    </div>

    <div className="input-group">
      <input type="text" placeholder="National ID" />
      <FaIdCard className="input-icon" />
    </div>

    <div className="input-group">
      <input type="text" placeholder="Username" />
      <FaUser className="input-icon" />
    </div>

    <div className="input-group">
      <input type="password" placeholder="Password" />
      <FaLock className="input-icon" />
    </div>

    <button className="btn-gradient">Create Account</button>

    <div className="login-link">
      Already have an account? <a href="/login">Login</a>
    </div>

  </div>

  {/* Shadows */}
  <div className="shadow-top-end"></div>
  <div className="shadow-bottom-start"></div>
</div>

    </div>
  );
};

export default Register;
